import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, isAbsolute, relative, resolve } from 'node:path';
import { FileStorage } from './file-storage';

const DEFAULT_DIR = 'storage/attachments';

/** Stores files under ATTACHMENTS_DIR; keys are generated by the server and never taken from the client. */
@Injectable()
export class DiskFileStorage extends FileStorage {
  private readonly logger = new Logger(DiskFileStorage.name);
  private readonly root: string;

  constructor(config: ConfigService) {
    super();
    const configured = config.get<string>('ATTACHMENTS_DIR');
    this.root = resolve(configured || DEFAULT_DIR);
    if (!configured && config.get<string>('NODE_ENV') === 'production') {
      this.logger.warn(
        `ATTACHMENTS_DIR is not set; files go to ${this.root}. Point it at a persistent, backed-up path outside the deploy directory.`,
      );
    }
  }

  async put(key: string, content: Buffer): Promise<void> {
    const path = this.pathFor(key);
    await mkdir(dirname(path), { recursive: true, mode: 0o750 });
    await writeFile(path, content, { flag: 'wx', mode: 0o640 });
  }

  async read(key: string): Promise<Buffer> {
    try {
      return await readFile(this.pathFor(key));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
        throw new NotFoundException('The stored file is missing');
      }
      throw error;
    }
  }

  async remove(key: string): Promise<void> {
    await rm(this.pathFor(key), { force: true });
  }

  // Defence in depth: a key can never point outside the storage root.
  private pathFor(key: string): string {
    const path = resolve(this.root, key);
    const inside = relative(this.root, path);
    if (!inside || inside.startsWith('..') || isAbsolute(inside)) {
      throw new Error('Invalid storage key');
    }
    return path;
  }
}
